func withJobs(t *testing.T, m Model, runs ...jobs.Run) Model {
	t.Helper()
	return feed(t, m, jobs.ChangedMsg{Runs: runs, Frame: "*", RenderedFrame: "*"})
}

// runningRun builds a run of one kind with every target already running.
